var o=[{id:`sample-index-01`,chapter:`Tlön, Uqbar, Orbis Tertius`,theme:`Realidad`,subtheme:`Construcción intelectual de mundos y transformación de lo real`,syncStatus:`synced`,tags:[`#realidad`]},{id:`sample-index-02`,chapter:`Pierre Menard, autor del Quijote`,theme:`Autoría`,subtheme:`Contexto, interpretación y relación entre autor y texto`,syncStatus:`synced`,tags:[`#autoría`]},{id:`sample-index-03`,chapter:`La biblioteca de Babel`,theme:`Infinito`,subtheme:`Conocimiento, lenguaje y totalidad`,syncStatus:`synced`,tags:[`#infinito`]},{id:`sample-index-04`,chapter:`El jardín de senderos que se bifurcan`,theme:`Tiempo`,subtheme:`Posibilidades simultáneas y caminos divergentes`,syncStatus:`synced`,tags:[`#tiempo`]},{id:`sample-index-05`,chapter:`Las ruinas circulares`,theme:`Identidad`,subtheme:`Creación, sueño y existencia`,syncStatus:`synced`,tags:[`#identidad`]},{id:`sample-index-06`,chapter:`Funes el memorioso`,theme:`Memoria`,subtheme:`Recuerdo absoluto, percepción y abstracción`,syncStatus:`synced`,tags:[`#memoria`]},{id:`sample-index-07`,chapter:`La lotería en Babilonia`,theme:`Azar`,subtheme:`Destino, orden y sistemas de incertidumbre`,syncStatus:`synced`,tags:[`#azar`]},{id:`sample-index-08`,chapter:`La muerte y la brújula`,theme:`Interpretación`,subtheme:`Patrones, razonamiento y exceso de significado`,syncStatus:`synced`,tags:[`#interpretación`]},{id:`sample-index-09`,chapter:`Tema del traidor y del héroe`,theme:`Historia`,subtheme:`Repetición, representación y construcción del pasado`,syncStatus:`synced`,tags:[`#historia`]},{id:`sample-index-10`,chapter:`Panorama analítico`,theme:`Laberinto`,subtheme:`Conocimiento, elecciones y estructuras potencialmente infinitas`,syncStatus:`synced`,tags:[`#laberinto`]}];var i=[{id:`sample-character-01`,name:`Ireneo Funes`,role:`protagonist`,nature:`fictitious`,description:`Personaje central de Funes el memorioso, asociado con una capacidad extraordinaria de percepción y memoria y con las dificultades de abstraer y generalizar.`,archetype:`Memoria absoluta`,source:`Ficciones`,tags:[`#funes`,`#memoria`,`#percepción`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`,color:`#6A994E`},{id:`sample-character-02`,name:`Pierre Menard`,role:`protagonist`,nature:`fictitious`,description:`Escritor ficticio cuya empresa literaria permite explorar la autoría, el contexto histórico y la transformación del significado de un texto.`,archetype:`Autor imposible`,source:`Ficciones`,tags:[`#menard`,`#autoría`,`#literatura`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`,color:`#5C4D7D`},{id:`sample-character-03`,name:`Yu Tsun`,role:`protagonist`,nature:`fictitious`,description:`Personaje central de El jardín de senderos que se bifurcan cuya historia conecta espionaje, decisiones, tiempo y múltiples posibilidades.`,archetype:`Agente ante la bifurcación`,source:`Ficciones`,tags:[`#yu-tsun`,`#tiempo`,`#decisión`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`,color:`#D17B49`},{id:`sample-character-04`,name:`Stephen Albert`,role:`supporting`,nature:`fictitious`,description:`Personaje vinculado con la interpretación del proyecto de Ts'ui Pên y con la concepción de un tiempo compuesto por posibilidades divergentes.`,archetype:`Intérprete del laberinto`,source:`Ficciones`,tags:[`#stephen-albert`,`#laberinto`,`#tiempo`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`,color:`#C49A3A`},{id:`sample-character-05`,name:`Ts'ui Pên`,role:`historical`,nature:`fictitious`,description:`Antepasado ficticio de Yu Tsun cuyo proyecto literario y laberíntico ocupa un lugar central en El jardín de senderos que se bifurcan.`,archetype:`Constructor de posibilidades`,source:`Ficciones`,tags:[`#tsui-pen`,`#laberinto`,`#literatura`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`,color:`#B56576`},{id:`sample-character-06`,name:`Erik Lönnrot`,role:`protagonist`,nature:`fictitious`,description:`Investigador de La muerte y la brújula cuya confianza en patrones intelectuales orienta su interpretación de una serie de acontecimientos.`,archetype:`Detective racionalista`,source:`Ficciones`,tags:[`#lönnrot`,`#interpretación`,`#patrones`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`,color:`#4F6D7A`},{id:`sample-character-07`,name:`Red Scharlach`,role:`antagonist`,nature:`fictitious`,description:`Adversario de Lönnrot en La muerte y la brújula, relacionado con el uso estratégico de patrones y expectativas.`,archetype:`Adversario estratégico`,source:`Ficciones`,tags:[`#scharlach`,`#lönnrot`,`#laberinto`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`,color:`#A44A3F`},{id:`sample-character-08`,name:`El soñador de las ruinas`,role:`protagonist`,nature:`fictitious`,description:`Figura central de Las ruinas circulares cuya empresa explora la creación, el sueño y la incertidumbre sobre la propia realidad.`,archetype:`Creador soñado`,source:`Ficciones`,tags:[`#ruinas-circulares`,`#sueño`,`#identidad`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`,color:`#3A7D44`},{id:`sample-character-09`,name:`Ryan`,role:`protagonist`,nature:`fictitious`,description:`Investigador de Tema del traidor y del héroe que examina acontecimientos históricos y descubre patrones vinculados con representación y repetición.`,archetype:`Investigador histórico`,source:`Ficciones`,tags:[`#ryan`,`#historia`,`#interpretación`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`,color:`#2F6690`},{id:`sample-character-10`,name:`El bibliotecario de Babel`,role:`supporting`,nature:`inspired`,description:`Figura analítica de muestra que representa a los habitantes y buscadores de la biblioteca infinita sin atribuirle una identidad canónica específica.`,archetype:`Buscador de conocimiento`,source:`Contexto analítico de muestra para Ficciones`,tags:[`#muestra-analítica`,`#biblioteca`,`#conocimiento`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`,color:`#735D78`}];var t=[{id:`sample-concept-01`,term:`Infinito`,definition:`Idea recurrente utilizada para explorar estructuras sin término aparente, posibilidades ilimitadas y los límites de la comprensión humana.`,category:`Concepto filosófico`,source:`Contexto de estudio para Ficciones`,tags:[`#conocimiento`,`#laberinto`,`#infinito`],syncStatus:`synced`},{id:`sample-concept-02`,term:`Laberinto`,definition:`Estructura física o conceptual que multiplica caminos, interpretaciones y posibilidades de orientación.`,category:`Símbolo literario`,source:`Contexto de estudio para Ficciones`,tags:[`#infinito`,`#interpretación`,`#laberinto`],syncStatus:`synced`},{id:`sample-concept-03`,term:`Tiempo divergente`,definition:`Modelo narrativo en el que diferentes posibilidades pueden concebirse como caminos temporales que se separan y multiplican.`,category:`Concepto filosófico`,source:`Contexto de estudio para Ficciones`,tags:[`#tiempo`,`#posibilidad`,`#tiempo-divergente`],syncStatus:`synced`},{id:`sample-concept-04`,term:`Identidad`,definition:`Problema filosófico y narrativo relacionado con la continuidad del yo, la duplicación, la creación y la incertidumbre sobre la propia existencia.`,category:`Tema`,source:`Contexto de estudio para Ficciones`,tags:[`#yo`,`#realidad`,`#identidad`],syncStatus:`synced`},{id:`sample-concept-05`,term:`Memoria absoluta`,definition:`Idea límite que permite examinar la relación entre recordar cada detalle, abstraer conceptos y pensar mediante generalizaciones.`,category:`Concepto filosófico`,source:`Contexto de estudio para Ficciones`,tags:[`#memoria`,`#conocimiento`,`#memoria-absoluta`],syncStatus:`synced`},{id:`sample-concept-06`,term:`Autoría`,definition:`Relación entre quien escribe, el contexto histórico de producción y los significados atribuidos a un texto.`,category:`Concepto literario`,source:`Contexto de estudio para Ficciones`,tags:[`#literatura`,`#interpretación`,`#autoría`],syncStatus:`synced`},{id:`sample-concept-07`,term:`Realidad construida`,definition:`Idea según la cual sistemas de lenguaje, conocimiento y representación pueden modificar la manera en que una realidad es comprendida.`,category:`Concepto filosófico`,source:`Contexto de estudio para Ficciones`,tags:[`#realidad`,`#lenguaje`,`#realidad-construida`],syncStatus:`synced`},{id:`sample-concept-08`,term:`Azar y orden`,definition:`Tensión entre acontecimientos aparentemente fortuitos y sistemas que intentan incorporarlos dentro de una estructura significativa.`,category:`Tema`,source:`Contexto de estudio para Ficciones`,tags:[`#azar`,`#destino`,`#azar-y-orden`],syncStatus:`synced`},{id:`sample-concept-09`,term:`Intertextualidad`,definition:`Relación entre textos reales o ficticios que produce nuevos niveles de interpretación y cuestiona las fronteras entre comentario, erudición y ficción.`,category:`Técnica narrativa`,source:`Contexto de estudio para Ficciones`,tags:[`#textos`,`#literatura`,`#intertextualidad`],syncStatus:`synced`},{id:`sample-concept-10`,term:`Conocimiento total`,definition:`Ideal problemático de reunir o acceder a toda la información posible, utilizado para examinar los límites de comprensión del individuo.`,category:`Concepto epistemológico`,source:`Contexto de estudio para Ficciones`,tags:[`#conocimiento`,`#infinito`,`#conocimiento-total`],syncStatus:`synced`}];var n=[{id:`sample-glosary-01`,term:`laberinto`,definition:`Construcción o estructura compleja compuesta por caminos que dificultan encontrar una salida o recorrido definitivo.`,partOfSpeech:`Noun`,etymology:`Del latín labyrinthus, procedente del griego labyrinthos.`,synonyms:[`dédalo`,`entramado`],contextSentence:`El laberinto puede representar tanto un espacio físico como una estructura de pensamiento.`,page:0,tags:[`#laberinto`,`#símbolo`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`},{id:`sample-glosary-02`,term:`infinito`,definition:`Aquello que no tiene o no parece tener límite o término.`,partOfSpeech:`Noun`,etymology:`Del latín infinitus, formado a partir de una negación y finitus, limitado.`,synonyms:[`ilimitado`,`interminable`],contextSentence:`Pensar una biblioteca infinita obliga a reconsiderar qué significaría encontrar un libro determinado.`,page:0,tags:[`#infinito`,`#biblioteca`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`},{id:`sample-glosary-03`,term:`paradoja`,definition:`Proposición o situación que produce una contradicción aparente o desafía las expectativas habituales.`,partOfSpeech:`Noun`,etymology:`Del griego paradoxos, relacionado con aquello contrario a la opinión común.`,synonyms:[`contradicción`,`incongruencia`],contextSentence:`Una paradoja puede convertir una idea aparentemente sencilla en un problema filosófico.`,page:0,tags:[`#paradoja`,`#filosofía`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`},{id:`sample-glosary-04`,term:`erudición`,definition:`Conocimiento amplio y profundo adquirido mediante el estudio, especialmente de textos y tradiciones culturales.`,partOfSpeech:`Noun`,etymology:`Del latín eruditio, relacionado con instrucción o conocimiento.`,synonyms:[`sabiduría`,`conocimiento`],contextSentence:`La erudición puede convertirse en parte del juego narrativo cuando se mezclan referencias auténticas y construcciones ficticias.`,page:0,tags:[`#erudición`,`#literatura`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`},{id:`sample-glosary-05`,term:`bifurcación`,definition:`División de un camino, proceso o estructura en dos o más direcciones.`,partOfSpeech:`Noun`,etymology:`Derivado del latín bifurcus, relacionado con una división en dos ramas.`,synonyms:[`división`,`ramificación`],contextSentence:`Cada bifurcación puede representar una decisión y, al mismo tiempo, una posibilidad no realizada.`,page:0,tags:[`#bifurcación`,`#tiempo`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`},{id:`sample-glosary-06`,term:`metaficción`,definition:`Ficción que llama la atención sobre su propio carácter de texto construido.`,partOfSpeech:`Noun`,etymology:`Formado por meta-, elemento asociado con reflexión sobre sí mismo, y ficción.`,synonyms:[`ficción autorreflexiva`],contextSentence:`La metaficción permite que un relato funcione simultáneamente como historia y reflexión sobre la literatura.`,page:0,tags:[`#metaficción`,`#literatura`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`},{id:`sample-glosary-07`,term:`simetría`,definition:`Correspondencia equilibrada entre partes, formas, acontecimientos o estructuras.`,partOfSpeech:`Noun`,etymology:`Del griego symmetria, relacionado con proporción y medida común.`,synonyms:[`correspondencia`,`equilibrio`],contextSentence:`La búsqueda de simetría puede revelar un patrón auténtico o hacer que el observador imagine uno inexistente.`,page:0,tags:[`#simetría`,`#patrones`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`},{id:`sample-glosary-08`,term:`conjetura`,definition:`Juicio o interpretación formulado a partir de indicios sin disponer de certeza completa.`,partOfSpeech:`Noun`,etymology:`Del latín coniectura, relacionado con inferencia o interpretación.`,synonyms:[`hipótesis`,`suposición`],contextSentence:`Una conjetura elegante puede resultar más seductora que una explicación sencilla.`,page:0,tags:[`#conjetura`,`#interpretación`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`},{id:`sample-glosary-09`,term:`identidad`,definition:`Condición mediante la cual una persona o cosa es considerada la misma a través de cambios, contextos o representaciones.`,partOfSpeech:`Noun`,etymology:`Del latín identitas, relacionado con la cualidad de ser lo mismo.`,synonyms:[`individualidad`,`mismidad`],contextSentence:`La identidad se vuelve problemática cuando una creación descubre que su propio origen puede repetirse.`,page:0,tags:[`#identidad`,`#realidad`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`},{id:`sample-glosary-10`,term:`interpretación`,definition:`Proceso de atribuir significado a un texto, acontecimiento, símbolo o conjunto de indicios.`,partOfSpeech:`Noun`,etymology:`Del latín interpretatio, relacionado con explicación o comprensión.`,synonyms:[`lectura`,`explicación`],contextSentence:`Una interpretación puede transformar detalles dispersos en un sistema coherente, aunque esa coherencia también debe ser cuestionada.`,page:0,tags:[`#interpretación`,`#lectura`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`}];var r=[{id:`sample-passage-01`,title:`La biblioteca imposible`,passageText:`Los corredores continuaban más allá de cuanto permitía comprobar la vista. Cada volumen prometía una respuesta, pero la cantidad de respuestas posibles convertía la búsqueda en otra forma de incertidumbre.`,book:`Ficciones`,author:`Jorge Luis Borges`,page:0,tags:[`#muestra`,`#biblioteca`,`#infinito`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`},{id:`sample-passage-02`,title:`El mismo texto`,passageText:`Las palabras eran idénticas, pero habían llegado desde otro siglo y otra intención. La semejanza material no consiguió impedir que cada frase adquiriera un significado diferente.`,book:`Ficciones`,author:`Jorge Luis Borges`,page:0,tags:[`#muestra`,`#autoría`,`#interpretación`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`},{id:`sample-passage-03`,title:`Senderos`,passageText:`Ante cada decisión imaginó que el camino rechazado continuaba en alguna parte. Pensar así transformaba una simple elección en una multiplicación silenciosa del mundo.`,book:`Ficciones`,author:`Jorge Luis Borges`,page:0,tags:[`#muestra`,`#tiempo`,`#posibilidad`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`},{id:`sample-passage-04`,title:`Memoria total`,passageText:`Nada desaparecía de su memoria. Precisamente por eso cada instante permanecía separado del siguiente con una precisión abrumadora, y reunir experiencias distintas bajo una sola idea se volvía cada vez más difícil.`,book:`Ficciones`,author:`Jorge Luis Borges`,page:0,tags:[`#muestra`,`#memoria`,`#abstracción`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`},{id:`sample-passage-05`,title:`El soñador`,passageText:`Había dedicado tanto esfuerzo a construir otra conciencia que rara vez examinaba la certeza de la propia. La pregunta sobre el creador regresó cuando menos deseaba formularla.`,book:`Ficciones`,author:`Jorge Luis Borges`,page:0,tags:[`#muestra`,`#sueño`,`#identidad`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`},{id:`sample-passage-06`,title:`El patrón`,passageText:`Tres señales parecían formar un diseño demasiado perfecto para ser accidental. El investigador siguió la geometría sin preguntarse primero quién podía beneficiarse de que él creyera en ella.`,book:`Ficciones`,author:`Jorge Luis Borges`,page:0,tags:[`#muestra`,`#interpretación`,`#patrones`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`},{id:`sample-passage-07`,title:`Un mundo inventado`,passageText:`Al principio era solamente una referencia dudosa entre páginas eruditas. Después aparecieron nuevos documentos, objetos y explicaciones, hasta que la invención comenzó a competir con la realidad que pretendía describir.`,book:`Ficciones`,author:`Jorge Luis Borges`,page:0,tags:[`#muestra`,`#realidad`,`#conocimiento`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`},{id:`sample-passage-08`,title:`La compañía invisible`,passageText:`Nadie podía determinar dónde terminaba el azar y dónde comenzaba la organización. Cada coincidencia podía ser una decisión secreta y cada decisión podía presentarse como coincidencia.`,book:`Ficciones`,author:`Jorge Luis Borges`,page:0,tags:[`#muestra`,`#azar`,`#orden`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`},{id:`sample-passage-09`,title:`La historia repetida`,passageText:`Los acontecimientos parecían conocidos porque otras historias habían preparado su forma. La investigación dejó de buscar únicamente lo ocurrido y comenzó a examinar el relato mediante el cual sería recordado.`,book:`Ficciones`,author:`Jorge Luis Borges`,page:0,tags:[`#muestra`,`#historia`,`#representación`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`},{id:`sample-passage-10`,title:`El centro del laberinto`,passageText:`Durante años buscó un centro que explicara todos los caminos. Finalmente sospechó que el laberinto no ocultaba una respuesta, sino que estaba construido con la necesidad misma de buscarla.`,book:`Ficciones`,author:`Jorge Luis Borges`,page:0,tags:[`#muestra`,`#laberinto`,`#conocimiento`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`}];var s=[{id:`sample-place-01`,name:`Biblioteca de Babel`,type:`building`,nature:`fictional`,coordinates:``,color:`#665C4A`,description:`Espacio ficticio asociado con una biblioteca de escala inconmensurable y con problemas de conocimiento, búsqueda, lenguaje e infinito.`,source:`Ficciones`,tags:[`#biblioteca-de-babel`,`#infinito`,`#conocimiento`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`},{id:`sample-place-02`,name:`Tlön`,type:`country`,nature:`fictional`,coordinates:``,color:`#596D7A`,description:`Mundo ficticio asociado con una construcción intelectual sistemática que forma parte central de Tlön, Uqbar, Orbis Tertius.`,source:`Ficciones`,tags:[`#tlön`,`#realidad`,`#filosofía`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`},{id:`sample-place-03`,name:`Uqbar`,type:`region`,nature:`fictional`,coordinates:``,color:`#7B6D58`,description:`Región ficticia cuya aparición en una referencia enciclopédica impulsa la investigación de Tlön, Uqbar, Orbis Tertius.`,source:`Ficciones`,tags:[`#uqbar`,`#enciclopedia`,`#realidad`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`},{id:`sample-place-04`,name:`Buenos Aires`,type:`city`,nature:`real`,coordinates:`-34.6037,-58.3816`,color:`#607D6D`,description:`Ciudad real presente o relevante como contexto urbano en varios relatos de Borges.`,source:`Contexto de estudio para Ficciones`,tags:[`#buenos-aires`,`#argentina`,`#borges`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`},{id:`sample-place-05`,name:`Argentina`,type:`country`,nature:`real`,coordinates:`-38.4161,-63.6167`,color:`#75AADB`,description:`País que proporciona parte del contexto geográfico y cultural de diversos relatos de la colección.`,source:`Contexto de estudio para Ficciones`,tags:[`#argentina`,`#contexto`,`#literatura`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`},{id:`sample-place-06`,name:`Jardín de senderos que se bifurcan`,type:`region`,nature:`fictional`,coordinates:``,color:`#527A58`,description:`Espacio conceptual y narrativo asociado con el laberinto, las bifurcaciones y una concepción múltiple del tiempo.`,source:`Ficciones`,tags:[`#jardín`,`#senderos`,`#tiempo`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`},{id:`sample-place-07`,name:`Ruinas circulares`,type:`building`,nature:`fictional`,coordinates:``,color:`#8B6F47`,description:`Espacio ficticio asociado con creación, sueño, identidad y los límites entre creador y creación.`,source:`Ficciones`,tags:[`#ruinas-circulares`,`#sueño`,`#identidad`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`},{id:`sample-place-08`,name:`Babilonia de la lotería`,type:`city`,nature:`fictional`,coordinates:``,color:`#AD8B56`,description:`Designación analítica del entorno ficticio de La lotería en Babilonia, asociado con azar, organización y destino.`,source:`Contexto analítico de muestra para Ficciones`,tags:[`#muestra-analítica`,`#babilonia`,`#azar`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`},{id:`sample-place-09`,name:`Laberinto textual`,type:`region`,nature:`inspired`,coordinates:``,color:`#6B6680`,description:`Entrada explícitamente analítica que representa las múltiples referencias, textos ficticios, comentarios y caminos interpretativos de la colección.`,source:`Contexto analítico de muestra para Ficciones`,tags:[`#muestra-analítica`,`#laberinto`,`#literatura`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`},{id:`sample-place-10`,name:`Biblioteca conceptual`,type:`institution`,nature:`inspired`,coordinates:``,color:`#625D52`,description:`Entrada explícitamente analítica que representa el conjunto de libros, referencias, autores reales e inventados y sistemas de conocimiento movilizados por los relatos.`,source:`Contexto analítico de muestra para Ficciones`,tags:[`#muestra-analítica`,`#libros`,`#conocimiento`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`}];var c=[{id:`sample-quote-01`,quote:`Un laberinto intelectual puede ser más difícil de abandonar que uno construido con muros.`,analysis:`Reflexión original sobre el laberinto como estructura física, narrativa y filosófica.`,author:`Sumaq Yachay Sample`,page:0,tags:[`#muestra`,`#laberinto`,`#pensamiento`],syncStatus:`synced`},{id:`sample-quote-02`,quote:`Una memoria perfecta podría conservar cada instante y, al mismo tiempo, dificultar aquello que llamamos pensar.`,analysis:`Reflexión original sobre memoria, abstracción y conocimiento.`,author:`Sumaq Yachay Sample`,page:0,tags:[`#muestra`,`#memoria`,`#conocimiento`],syncStatus:`synced`},{id:`sample-quote-03`,quote:`Dos textos idénticos pueden dejar de ser el mismo texto cuando pertenecen a historias distintas.`,analysis:`Reflexión original sobre autoría, contexto e interpretación.`,author:`Sumaq Yachay Sample`,page:0,tags:[`#muestra`,`#autoría`,`#interpretación`],syncStatus:`synced`},{id:`sample-quote-04`,quote:`Cada decisión parece cerrar un camino solamente porque no podemos seguir todos los caminos a la vez.`,analysis:`Reflexión original sobre bifurcación, tiempo y posibilidad.`,author:`Sumaq Yachay Sample`,page:0,tags:[`#muestra`,`#tiempo`,`#posibilidad`],syncStatus:`synced`},{id:`sample-quote-05`,quote:`Una biblioteca que contiene todas las respuestas también contiene demasiadas respuestas falsas para cada pregunta.`,analysis:`Reflexión original sobre información infinita y los límites prácticos del conocimiento.`,author:`Sumaq Yachay Sample`,page:0,tags:[`#muestra`,`#biblioteca`,`#conocimiento`],syncStatus:`synced`},{id:`sample-quote-06`,quote:`La realidad se vuelve vulnerable cuando una ficción ofrece un sistema más completo para explicarla.`,analysis:`Reflexión original sobre mundos construidos, conocimiento y realidad.`,author:`Sumaq Yachay Sample`,page:0,tags:[`#muestra`,`#realidad`,`#ficción`],syncStatus:`synced`},{id:`sample-quote-07`,quote:`Encontrar un patrón no demuestra que el mundo lo haya construido para nosotros.`,analysis:`Reflexión original sobre interpretación, razonamiento y la búsqueda de estructuras significativas.`,author:`Sumaq Yachay Sample`,page:0,tags:[`#muestra`,`#patrones`,`#interpretación`],syncStatus:`synced`},{id:`sample-quote-08`,quote:`El creador empieza a dudar de su posición cuando descubre que también podría formar parte de una creación.`,analysis:`Reflexión original sobre sueño, identidad y niveles de realidad.`,author:`Sumaq Yachay Sample`,page:0,tags:[`#muestra`,`#identidad`,`#realidad`],syncStatus:`synced`},{id:`sample-quote-09`,quote:`La historia puede repetirse porque los acontecimientos se repiten o porque aprendemos a narrarlos con formas conocidas.`,analysis:`Reflexión original sobre representación histórica, repetición e intertextualidad.`,author:`Sumaq Yachay Sample`,page:0,tags:[`#muestra`,`#historia`,`#repetición`],syncStatus:`synced`},{id:`sample-quote-10`,quote:`El infinito no necesita ser recorrido por completo para alterar nuestra idea de lo posible.`,analysis:`Reflexión original sobre infinito, conocimiento e imaginación.`,author:`Sumaq Yachay Sample`,page:0,tags:[`#muestra`,`#infinito`,`#posibilidad`],syncStatus:`synced`}];var d=[];var l=[{id:`sample-book-event-01`,displayRow:1,mainCharacterId:`book-es-005-sample-character-01`,secondaryCharacterIds:[`book-es-005-sample-character-02`,`book-es-005-sample-character-03`],placeId:`book-es-005-sample-place-01`,dateLabel:`Tlön, Uqbar, Orbis Tertius`,eventOrder:1,event:`Evento de estudio 1: Tlön, Uqbar, Orbis Tertius / Realidad`,description:`Síntesis de estudio para «Tlön, Uqbar, Orbis Tertius»: el índice destaca Realidad (Construcción intelectual de mundos y transformación de lo real). La descripción de Ireneo Funes («Personaje central de Funes el memorioso, asociado con una capacidad extraordinaria de percepción y memoria y con las dificultades de abstraer y generalizar.») se relaciona aquí con el concepto Infinito («Idea recurrente utilizada para explorar estructuras sin término aparente, posibilidades ilimitadas y los límites de la comprensión humana.»). Biblioteca de Babel y el pasaje «La biblioteca imposible» añaden contexto del escenario y la lectura. Esta entrada organiza el material de muestra y debe contrastarse con la edición del libro.`,color:`#6A994E`,book:`Ficciones`,author:`Jorge Luis Borges`,page:``,tags:[`#realidad`,`#funes`,`#memoria`,`#percepción`,`#infinito`,`#conocimiento`,`#laberinto`,`#biblioteca-de-babel`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`},{id:`sample-book-event-02`,displayRow:2,mainCharacterId:`book-es-005-sample-character-03`,secondaryCharacterIds:[`book-es-005-sample-character-04`,`book-es-005-sample-character-05`],placeId:`book-es-005-sample-place-02`,dateLabel:`Pierre Menard, autor del Quijote`,eventOrder:2,event:`Evento de estudio 2: Pierre Menard, autor del Quijote / Autoría`,description:`Síntesis de estudio para «Pierre Menard, autor del Quijote»: el índice destaca Autoría (Contexto, interpretación y relación entre autor y texto). La descripción de Yu Tsun («Personaje central de El jardín de senderos que se bifurcan cuya historia conecta espionaje, decisiones, tiempo y múltiples posibilidades.») se relaciona aquí con el concepto Tiempo divergente («Modelo narrativo en el que diferentes posibilidades pueden concebirse como caminos temporales que se separan y multiplican.»). Tlön y el pasaje «El mismo texto» añaden contexto del escenario y la lectura. Esta entrada organiza el material de muestra y debe contrastarse con la edición del libro.`,color:`#D17B49`,book:`Ficciones`,author:`Jorge Luis Borges`,page:``,tags:[`#autoría`,`#yu-tsun`,`#tiempo`,`#decisión`,`#tiempo-divergente`,`#posibilidad`,`#tlön`,`#realidad`,`#filosofía`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`},{id:`sample-book-event-03`,displayRow:3,mainCharacterId:`book-es-005-sample-character-05`,secondaryCharacterIds:[`book-es-005-sample-character-06`,`book-es-005-sample-character-07`],placeId:`book-es-005-sample-place-03`,dateLabel:`La biblioteca de Babel`,eventOrder:3,event:`Evento de estudio 3: La biblioteca de Babel / Infinito`,description:`Síntesis de estudio para «La biblioteca de Babel»: el índice destaca Infinito (Conocimiento, lenguaje y totalidad). La descripción de Ts'ui Pên («Antepasado ficticio de Yu Tsun cuyo proyecto literario y laberíntico ocupa un lugar central en El jardín de senderos que se bifurcan.») se relaciona aquí con el concepto Memoria absoluta («Idea límite que permite examinar la relación entre recordar cada detalle, abstraer conceptos y pensar mediante generalizaciones.»). Uqbar y el pasaje «Senderos» añaden contexto del escenario y la lectura. Esta entrada organiza el material de muestra y debe contrastarse con la edición del libro.`,color:`#B56576`,book:`Ficciones`,author:`Jorge Luis Borges`,page:``,tags:[`#infinito`,`#tsui-pen`,`#laberinto`,`#literatura`,`#memoria-absoluta`,`#memoria`,`#conocimiento`,`#uqbar`,`#enciclopedia`,`#realidad`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`},{id:`sample-book-event-04`,displayRow:4,mainCharacterId:`book-es-005-sample-character-07`,secondaryCharacterIds:[`book-es-005-sample-character-08`,`book-es-005-sample-character-09`],placeId:`book-es-005-sample-place-04`,dateLabel:`El jardín de senderos que se bifurcan`,eventOrder:4,event:`Evento de estudio 4: El jardín de senderos que se bifurcan / Tiempo`,description:`Síntesis de estudio para «El jardín de senderos que se bifurcan»: el índice destaca Tiempo (Posibilidades simultáneas y caminos divergentes). La descripción de Red Scharlach («Adversario de Lönnrot en La muerte y la brújula, relacionado con el uso estratégico de patrones y expectativas.») se relaciona aquí con el concepto Realidad construida («Idea según la cual sistemas de lenguaje, conocimiento y representación pueden modificar la manera en que una realidad es comprendida.»). Buenos Aires y el pasaje «Memoria total» añaden contexto del escenario y la lectura. Esta entrada organiza el material de muestra y debe contrastarse con la edición del libro.`,color:`#A44A3F`,book:`Ficciones`,author:`Jorge Luis Borges`,page:``,tags:[`#tiempo`,`#scharlach`,`#lönnrot`,`#laberinto`,`#realidad-construida`,`#realidad`,`#lenguaje`,`#buenos-aires`,`#argentina`,`#borges`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`}];var u=[{id:`sample-character-relation-01`,displayRow:1,sourceCharacterId:`book-es-005-sample-character-01`,targetCharacterId:`book-es-005-sample-character-02`,relationType:`comparación temática`,directed:!1,description:`Esta asociación de lectura vincula Ireneo Funes (Personaje central de Funes el memorioso, asociado con una capacidad extraordinaria de percepción y memoria y con las dificultades de abstraer y generalizar.) con Pierre Menard (Escritor ficticio cuya empresa literaria permite explorar la autoría, el contexto histórico y la transformación del significado de un texto.). El tema «Realidad» y el subtema «Construcción intelectual de mundos y transformación de lo real» orientan la comparación; el pasaje «La biblioteca imposible» aporta contexto del propio libro. Es una conexión interpretativa basada en estas entradas, no una afirmación de que ambos personajes compartan una escena.`,color:`#6A994E`,book:`Ficciones`,author:`Jorge Luis Borges`,page:``,tags:[`#funes`,`#memoria`,`#percepción`,`#menard`,`#autoría`,`#literatura`,`#realidad`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`},{id:`sample-character-relation-02`,displayRow:2,sourceCharacterId:`book-es-005-sample-character-03`,targetCharacterId:`book-es-005-sample-character-04`,relationType:`perspectivas en contraste`,directed:!1,description:`Esta asociación de lectura vincula Yu Tsun (Personaje central de El jardín de senderos que se bifurcan cuya historia conecta espionaje, decisiones, tiempo y múltiples posibilidades.) con Stephen Albert (Personaje vinculado con la interpretación del proyecto de Ts'ui Pên y con la concepción de un tiempo compuesto por posibilidades divergentes.). El tema «Autoría» y el subtema «Contexto, interpretación y relación entre autor y texto» orientan la comparación; el pasaje «El mismo texto» aporta contexto del propio libro. Es una conexión interpretativa basada en estas entradas, no una afirmación de que ambos personajes compartan una escena.`,color:`#D17B49`,book:`Ficciones`,author:`Jorge Luis Borges`,page:``,tags:[`#yu-tsun`,`#tiempo`,`#decisión`,`#stephen-albert`,`#laberinto`,`#autoría`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`},{id:`sample-character-relation-03`,displayRow:3,sourceCharacterId:`book-es-005-sample-character-05`,targetCharacterId:`book-es-005-sample-character-06`,relationType:`contexto narrativo compartido`,directed:!1,description:`Esta asociación de lectura vincula Ts'ui Pên (Antepasado ficticio de Yu Tsun cuyo proyecto literario y laberíntico ocupa un lugar central en El jardín de senderos que se bifurcan.) con Erik Lönnrot (Investigador de La muerte y la brújula cuya confianza en patrones intelectuales orienta su interpretación de una serie de acontecimientos.). El tema «Infinito» y el subtema «Conocimiento, lenguaje y totalidad» orientan la comparación; el pasaje «Senderos» aporta contexto del propio libro. Es una conexión interpretativa basada en estas entradas, no una afirmación de que ambos personajes compartan una escena.`,color:`#B56576`,book:`Ficciones`,author:`Jorge Luis Borges`,page:``,tags:[`#tsui-pen`,`#laberinto`,`#literatura`,`#lönnrot`,`#interpretación`,`#patrones`,`#infinito`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`},{id:`sample-character-relation-04`,displayRow:4,sourceCharacterId:`book-es-005-sample-character-07`,targetCharacterId:`book-es-005-sample-character-08`,relationType:`asociación interpretativa`,directed:!1,description:`Esta asociación de lectura vincula Red Scharlach (Adversario de Lönnrot en La muerte y la brújula, relacionado con el uso estratégico de patrones y expectativas.) con El soñador de las ruinas (Figura central de Las ruinas circulares cuya empresa explora la creación, el sueño y la incertidumbre sobre la propia realidad.). El tema «Tiempo» y el subtema «Posibilidades simultáneas y caminos divergentes» orientan la comparación; el pasaje «Memoria total» aporta contexto del propio libro. Es una conexión interpretativa basada en estas entradas, no una afirmación de que ambos personajes compartan una escena.`,color:`#A44A3F`,book:`Ficciones`,author:`Jorge Luis Borges`,page:``,tags:[`#scharlach`,`#lönnrot`,`#laberinto`,`#ruinas-circulares`,`#sueño`,`#identidad`,`#tiempo`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`}];var p=[{id:`sample-concept-relation-01`,displayRow:1,sourceConceptId:`book-es-005-sample-concept-01`,targetConceptId:`book-es-005-sample-concept-02`,relationType:`da contexto a`,directed:!0,description:`La definición de «Infinito» («Idea recurrente utilizada para explorar estructuras sin término aparente, posibilidades ilimitadas y los límites de la comprensión humana.») puede leerse en relación con «Laberinto» («Estructura física o conceptual que multiplica caminos, interpretaciones y posibilidades de orientación.»). El tema Realidad y el subtema Construcción intelectual de mundos y transformación de lo real, junto con el pasaje «La biblioteca imposible», sitúan esta conexión conceptual dentro del contexto de lectura del libro.`,color:`#735D78`,book:`Ficciones`,author:`Jorge Luis Borges`,page:``,tags:[`#infinito`,`#conocimiento`,`#laberinto`,`#interpretación`,`#realidad`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`},{id:`sample-concept-relation-02`,displayRow:2,sourceConceptId:`book-es-005-sample-concept-03`,targetConceptId:`book-es-005-sample-concept-04`,relationType:`ofrece una perspectiva sobre`,directed:!1,description:`La definición de «Tiempo divergente» («Modelo narrativo en el que diferentes posibilidades pueden concebirse como caminos temporales que se separan y multiplican.») puede leerse en relación con «Identidad» («Problema filosófico y narrativo relacionado con la continuidad del yo, la duplicación, la creación y la incertidumbre sobre la propia existencia.»). El tema Autoría y el subtema Contexto, interpretación y relación entre autor y texto, junto con el pasaje «El mismo texto», sitúan esta conexión conceptual dentro del contexto de lectura del libro.`,color:`#2F6690`,book:`Ficciones`,author:`Jorge Luis Borges`,page:``,tags:[`#tiempo-divergente`,`#tiempo`,`#posibilidad`,`#identidad`,`#yo`,`#realidad`,`#autoría`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`},{id:`sample-concept-relation-03`,displayRow:3,sourceConceptId:`book-es-005-sample-concept-05`,targetConceptId:`book-es-005-sample-concept-06`,relationType:`contrasta con`,directed:!1,description:`La definición de «Memoria absoluta» («Idea límite que permite examinar la relación entre recordar cada detalle, abstraer conceptos y pensar mediante generalizaciones.») puede leerse en relación con «Autoría» («Relación entre quien escribe, el contexto histórico de producción y los significados atribuidos a un texto.»). El tema Infinito y el subtema Conocimiento, lenguaje y totalidad, junto con el pasaje «Senderos», sitúan esta conexión conceptual dentro del contexto de lectura del libro.`,color:`#A44A3F`,book:`Ficciones`,author:`Jorge Luis Borges`,page:``,tags:[`#memoria-absoluta`,`#memoria`,`#conocimiento`,`#autoría`,`#literatura`,`#interpretación`,`#infinito`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`},{id:`sample-concept-relation-04`,displayRow:4,sourceConceptId:`book-es-005-sample-concept-07`,targetConceptId:`book-es-005-sample-concept-08`,relationType:`complementa`,directed:!0,description:`La definición de «Realidad construida» («Idea según la cual sistemas de lenguaje, conocimiento y representación pueden modificar la manera en que una realidad es comprendida.») puede leerse en relación con «Azar y orden» («Tensión entre acontecimientos aparentemente fortuitos y sistemas que intentan incorporarlos dentro de una estructura significativa.»). El tema Tiempo y el subtema Posibilidades simultáneas y caminos divergentes, junto con el pasaje «Memoria total», sitúan esta conexión conceptual dentro del contexto de lectura del libro.`,color:`#5C4D7D`,book:`Ficciones`,author:`Jorge Luis Borges`,page:``,tags:[`#realidad-construida`,`#realidad`,`#lenguaje`,`#azar-y-orden`,`#azar`,`#destino`,`#tiempo`],feed:1,contributor:`Local Sample Data`,syncStatus:`synced`}];var m={INDEX:o,CHARACTER:i,CONCEPTS:t,GLOSARY:n,PASSAGES:r,PLACES:s,QUOTES:c,QUESTIONS:d,BOOK_EVENTS:l,RELATIONS:u,ASSOCIATIONS:p};export{p as ASSOCIATIONS,l as BOOK_EVENTS,i as CHARACTER,t as CONCEPTS,n as GLOSARY,o as INDEX,r as PASSAGES,s as PLACES,d as QUESTIONS,c as QUOTES,u as RELATIONS,m as default};